function fold(s) {
  return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const STEP_ORDER = [
  'awaiting_nombre',
  'awaiting_dni',
  'awaiting_obra_social',
  'awaiting_obra_social_otra',
  'awaiting_telefono',
  'awaiting_medico',
  'awaiting_dia_hora',
  'awaiting_confirmacion',
];

function quotedStep(texto) {
  const f = fold(texto);
  if (/confirmas el turno/.test(f)) return 'awaiting_confirmacion';
  if (/nombre completo/.test(f)) return 'awaiting_nombre';
  if (/cual es tu dni|tu dni|\bdni\b/.test(f)) return 'awaiting_dni';
  if (/nombre de tu obra social/.test(f)) return 'awaiting_obra_social_otra';
  if (/obra social/.test(f)) return 'awaiting_obra_social';
  if (/numero de telefono/.test(f)) return 'awaiting_telefono';
  if (/medico preferis|que medico/.test(f)) return 'awaiting_medico';
  if (/horario preferis/.test(f)) return 'awaiting_confirmacion';
  return null;
}

const j = $input.first().json;
const estado = j.estado || 'idle';
const boton = String(j.boton_id || '').trim();
let texto = String(j.texto || '').trim();
texto = texto.replace(/\n?__cw_in_reply_to__:\S+/g, '').trim();
const lines = texto.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
const last = lines.length ? lines[lines.length - 1] : texto;
const lastFold = fold(last);
const isNavLine = (l) => /^(repetir|repetir pregunta)$/i.test(fold(l));
const isRepetir = boton === 'repetir_pregunta' || isNavLine(last) || lines.some(isNavLine);
const isConfirm = boton === 'confirmar_turno'
  || /^(si|ok|okay|confirmar|confirmo|dale|yes)$/i.test(lastFold);
const ctx = parseCtx(j.datos_json);
let step = estado;
if (/^(idle|menu_shown)$/.test(estado)) step = 'Empezar';

if (isRepetir) {
  const q = quotedStep(texto);
  if (q) {
    const cur = STEP_ORDER.indexOf(step);
    const tgt = STEP_ORDER.indexOf(q);
    if (tgt >= 0 && (cur < 0 || tgt <= cur)) step = q;
  }
}

return [{
  json: {
    telefono: j.telefono,
    texto,
    boton_id: boton,
    estado,
    datos_json: ctx,
    conversation_id: j.conversation_id,
    account_id: j.account_id,
    is_repetir: isRepetir,
    is_confirm: isConfirm,
    step
  }
}];

